    do { v /= 1024; i++; } while (v >= 1024 && i < u.length - 1);
    return (v >= 10 ? v.toFixed(0) : v.toFixed(1)) + ' ' + u[i];
  }

  function navigate(p) {
    var node = nodeAt(p);
    if (!node || node.type !== 'dir') return;
    cwd = p;
    render();
  }

  function render() {
    pathEl.textContent = cwd;
    listEl.innerHTML = '';
    var node = nodeAt(cwd);
    var children = (node && node.children) || {};
    var names = Object.keys(children);

    names.sort(function (a, b) {
      var da = children[a].type === 'dir', db = children[b].type === 'dir';
      if (da !== db) return da ? -1 : 1;
      return a.localeCompare(b);
    });

    var dirs = 0, files = 0;
    names.forEach(function (name) {
      var child = children[name];
      var isDir = child.type === 'dir';
      isDir ? dirs++ : files++;

      var el = document.createElement('div');
      el.className = 'fs-item ' + (isDir ? 'folder' : 'file');
      el.dataset.name = name;
      el.dataset.type = isDir ? 'dir' : 'file';
      el.title = joinPath(cwd, name) + (isDir ? '' : '  —  ' + humanSize(child.size));

      var g = document.createElement('span');
      g.className = 'glyph';
      g.textContent = isDir ? '🗀' : '🗎';
      el.appendChild(g);
      el.appendChild(document.createTextNode(name));

      el.addEventListener('click', function () {
        var sel = listEl.querySelector('.fs-item.selected');
        if (sel) sel.classList.remove('selected');
        el.classList.add('selected');
        statusEl.textContent = isDir
          ? 'Folder "' + name + '" selected — double-click to open'
          : '"' + name + '" — ' + humanSize(child.size);
      });

      el.addEventListener('dblclick', function () {
        if (isDir) {
          navigate(joinPath(cwd, name));
        } else {
          statusEl.textContent = '"' + name + '" — ' + humanSize(child.size) + ' (no application associated)';
        }
      });

      listEl.appendChild(el);
    });

    if (!names.length) statusEl.textContent = 'This folder is empty';
    else statusEl.textContent = names.length + ' items — ' + dirs + ' folders, ' + files + ' files';
  }

  document.getElementById('files-up').addEventListener('click', function () {
    navigate(parentPath(cwd));
  });
  document.getElementById('files-home').addEventListener('click', function () {
    navigate('/home/user');
  });
  Array.prototype.forEach.call(document.querySelectorAll('.place'), function (p) {
    p.addEventListener('click', function () { navigate(p.dataset.path); });
  });

  render();

  /* =========================================================
     Notepad — tabbed, persisted in localStorage
     ========================================================= */
  var STORE_KEY = 'ubuntu-desktop-notepad-v1';
  var tabsEl   = document.getElementById('tabs');
  var editor   = document.getElementById('editor');
  var npInfo   = document.getElementById('np-info');
  var npSaved  = document.getElementById('np-saved');

  var state = { tabs: [], activeId: null, seq: 1 };

  function safeGet() {
    try { return window.localStorage.getItem(STORE_KEY); } catch (e) { return null; }
  }
  function save() {
    try { window.localStorage.setItem(STORE_KEY, JSON.stringify(state)); } catch (e) {}
  }

  function load() {
    var raw = safeGet();
    if (raw) {
      try {
        var parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.tabs) && parsed.tabs.length) {
          state.tabs = parsed.tabs.map(function (t, i) {
            return {
              id: String(t.id != null ? t.id : 'tab-' + (i + 1)),
              title: typeof t.title === 'string' && t.title ? t.title : 'Untitled ' + (i + 1),
              content: typeof t.content === 'string' ? t.content : ''
            };
          });
          state.seq = typeof parsed.seq === 'number' ? parsed.seq : state.tabs.length + 1;
          var found = state.tabs.some(function (t) { return t.id === parsed.activeId; });
          state.activeId = found ? parsed.activeId : state.tabs[0].id;
          return;
        }
      } catch (e) { /* corrupt storage → fall through to defaults */ }
    }
    state.tabs = [];
    state.seq = 1;
    state.activeId = null;
    newTab('Untitled 1', 'Welcome to Notepad.\n\nTabs and their text are saved in localStorage —\nclose this window or reload the page and everything comes back.\n');
  }

  function newTab(title, content) {
    var id = 'tab-' + state.seq;
    var t = { id: id, title: title || ('Untitled ' + state.seq), content: content || '' };
    state.seq++;
    state.tabs.push(t);
    state.activeId = id;
    save();
    return t;
  }

  function activeTab() {
    for (var i = 0; i < state.tabs.length; i++) {
      if (state.tabs[i].id === state.activeId) return state.tabs[i];
    }
    return state.tabs[0] || null;
  }

  function renderTabs() {
    tabsEl.innerHTML = '';
    state.tabs.forEach(function (t) {
      var el = document.createElement('div');
      el.className = 'tab' + (t.id === state.activeId ? ' active' : '');
      el.dataset.id = t.id;
      el.title = t.title;

      var name = document.createElement('span');
      name.className = 'tab-name';
      name.textContent = t.title;
      el.appendChild(name);

      var x = document.createElement('button');
      x.className = 'tab-close';
      x.textContent = '✕';
      x.title = 'Close tab';
      x.addEventListener('click', function (e) {
        e.stopPropagation();
        closeTab(t.id);
      });
      el.appendChild(x);

      el.addEventListener('click', function () { switchTo(t.id); });
      tabsEl.appendChild(el);
    });
    npInfo.textContent = state.tabs.length + (state.tabs.length === 1 ? ' tab' : ' tabs');
  }

  function switchTo(id) {
    if (state.activeId === id) return;
    syncEditorToState();
    state.activeId = id;
    save();
    renderTabs();
    loadActiveIntoEditor();
  }

  function closeTab(id) {
    var idx = -1;
    for (var i = 0; i < state.tabs.length; i++) if (state.tabs[i].id === id) idx = i;
    if (idx === -1) return;
    state.tabs.splice(idx, 1);
    if (!state.tabs.length) {
      newTab('Untitled ' + state.seq, '');
    } else if (state.activeId === id) {
      state.activeId = state.tabs[Math.max(0, idx - 1)].id;
