    save();
    renderTabs();
    loadActiveIntoEditor();
  }

  function loadActiveIntoEditor() {
    var t = activeTab();
    editor.value = t ? t.content : '';
    editor.disabled = !t;
  }

  function syncEditorToState() {
    var t = activeTab();
    if (t) t.content = editor.value;
  }

  function titleFromContent(text) {
    var firstLine = (text.split('\n')[0] || '').trim();
    if (!firstLine) return null;
    return firstLine.length > 22 ? firstLine.slice(0, 22) + '…' : firstLine;
  }

  editor.addEventListener('input', function () {
    var t = activeTab();
    if (!t) return;
    t.content = editor.value;
    var auto = titleFromContent(editor.value);
    var newTitle = auto || 'Untitled';
    if (t.title !== newTitle) {
      t.title = newTitle;
      renderTabs();
    }
    save();
    npSaved.textContent = 'Saved · ' + editor.value.length + ' chars';
  });

  document.getElementById('new-tab').addEventListener('click', function () {
    syncEditorToState();
    newTab();
    renderTabs();
    loadActiveIntoEditor();
    editor.focus();
  });

  window.addEventListener('beforeunload', function () { syncEditorToState(); save(); });

  load();
  renderTabs();
  loadActiveIntoEditor();

